import re

from moler.exceptions import ParsingDone

from ta_moler.cmd.emssim.genericemssim import GenericEMSSIMCommand

__author__ = 'Marcin Usielski'
__copyright__ = 'Copyright (C) 2018, Nokia'
__email__ = 'marcin.usielski@nokia.com'


class Env(GenericEMSSIMCommand):
    """Env command class."""

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        return "env"

    def on_new_line(self, line, is_full_line):
        """
        To parse command output. will be called after line with command echo.

        Write your own implementation but don't forget to call on_new_line from base class.

        :param line: Line to parse, new lines are trimmed
        :param is_full_line:  False for chunk of line; True on full line (NOTE: new line character removed)
        :return: None
        """
        if is_full_line:
            try:
                self._parse_param_line(line)
                self._parse_start_param_line(line)
            except ParsingDone:
                pass  # line has been fully parsed by one of above parse-methods
        return super(Env, self).on_new_line(line, is_full_line)

    # Logfile                  : NOT LOGGING
    _re_param_line = re.compile(r'(?P<NAME>\w.*[\w\)])\s*:\s+(?P<VALUE>\S.*\S|\S+)')

    def _parse_param_line(self, line):
        self._parse(line, Env._re_param_line)

    # -SERVER_PORT 7001
    _re_start_param = re.compile(r'(?P<NAME>-[\w_]+)\s+(?P<VALUE>\S+)')

    def _parse_start_param_line(self, line):
        self._parse(line, Env._re_start_param)

    def _parse(self, line, regex):
        if self._regex_helper.search_compiled(regex, line):
            self.current_ret[self._regex_helper.group("NAME")] = self._regex_helper.group("VALUE")
            raise ParsingDone()


